import React, { useState, useEffect, useMemo } from "react";
import {
  LayoutDashboard, Package, ShoppingBag, Users, UserCog, LogOut,
  Plus, Pencil, Trash2, X, AlertTriangle, Check, ChevronDown, ChevronRight,
  Cookie, ArrowDownCircle, ArrowUpCircle, Lock, PackageX
} from "lucide-react";

const DB_KEY = "lecooki-db";

const LOGO_DATA_URI = "data:image/jpeg;base64,";

const seedDB = () => ({
  users: [
    { id: "u1", username: "admin", password: "admin123", nome: "Administradora", role: "admin" }
  ],
  products: [],
  sales: [],
  stockMovements: [],
  resellers: [],
  consignments: []
});

const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
const todayISO = () => new Date().toISOString().slice(0, 10);
const fmtBRL = (v) => (Number(v) || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const fmtDate = (d) => {
  if (!d) return "-";
  const [y, m, day] = d.split("-");
  return `${day}/${m}/${y}`;
};

function Modal({ title, onClose, children, wide }) {
  return (
    <div className="lc-modal-overlay" onClick={onClose}>
      <div className={"lc-modal" + (wide ? " lc-modal-wide" : "")} onClick={(e) => e.stopPropagation()}>
        <div className="lc-modal-head">
          <h3>{title}</h3>
          <button className="lc-icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="lc-modal-body">{children}</div>
      </div>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <label className="lc-field">
      <span>{label}</span>
      {children}
    </label>
  );
}

function StatCard({ icon, label, value, tone }) {
  return (
    <div className={"lc-stat lc-tone-" + (tone || "default")}>
      <div className="lc-stat-icon">{icon}</div>
      <div>
        <div className="lc-stat-value">{value}</div>
        <div className="lc-stat-label">{label}</div>
      </div>
    </div>
  );
}

export default function App() {
  const [db, setDb] = useState(null);
  const [loading, setLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState(null);
  const [activeTab, setActiveTab] = useState("dashboard");
  const [toast, setToast] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(DB_KEY, true);
        setDb(JSON.parse(res.value));
      } catch (e) {
        const seed = seedDB();
        setDb(seed);
        try { await window.storage.set(DB_KEY, JSON.stringify(seed), true); } catch (err) {}
      }
      setLoading(false);
    })();
  }, []);

  const persist = async (newDb) => {
    setDb(newDb);
    try {
      const ok = await window.storage.set(DB_KEY, JSON.stringify(newDb), true);
      if (!ok) showToast("Não foi possível salvar. Tente novamente.", "erro");
    } catch (e) {
      showToast("Erro ao salvar os dados.", "erro");
    }
  };

  const showToast = (msg, type = "ok") => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 2600);
  };

  if (loading) {
    return (
      <div className="lc-root lc-center">
        <style>{CSS}</style>
        <div className="lc-loading"><Cookie size={28} className="lc-spin" /> Carregando…</div>
      </div>
    );
  }

  if (!currentUser) {
    return (
      <div className="lc-root">
        <style>{CSS}</style>
        <LoginScreen db={db} onLogin={setCurrentUser} />
      </div>
    );
  }

  return (
    <div className="lc-root">
      <style>{CSS}</style>
      <div className="lc-app">
        <Sidebar
          currentUser={currentUser}
          activeTab={activeTab}
          setActiveTab={setActiveTab}
          onLogout={() => setCurrentUser(null)}
        />
        <main className="lc-main">
          {activeTab === "dashboard" && <Dashboard db={db} />}
          {activeTab === "estoque" && <Estoque db={db} persist={persist} showToast={showToast} currentUser={currentUser} />}
          {activeTab === "vendas" && <Vendas db={db} persist={persist} showToast={showToast} currentUser={currentUser} />}
          {activeTab === "revendedores" && <Revendedores db={db} persist={persist} showToast={showToast} />}
          {activeTab === "usuarios" && currentUser.role === "admin" && (
            <Usuarios db={db} persist={persist} showToast={showToast} currentUser={currentUser} />
          )}
        </main>
      </div>
      {toast && <div className={"lc-toast lc-toast-" + toast.type}>{toast.msg}</div>}
    </div>
  );
}

function LoginScreen({ db, onLogin }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [err, setErr] = useState("");

  const submit = (e) => {
    e.preventDefault();
    const u = db.users.find(
      (x) => x.username.toLowerCase() === username.trim().toLowerCase() && x.password === password
    );
    if (!u) {
      setErr("Usuário ou senha incorretos.");
      return;
    }
    setErr("");
    onLogin(u);
  };

  return (
    <div className="lc-login-wrap">
      <div className="lc-login-card">
        <div className="lc-login-logo">
          <img src={LOGO_DATA_URI} alt="Le Cooki" />
        </div>
        <h1>Le Cooki</h1>
        <p className="lc-login-sub">Sistema interno · estoque, vendas e revendedores</p>
        <form onSubmit={submit}>
          <Field label="Usuário">
            <input value={username} onChange={(e) => setUsername(e.target.value)} autoFocus />
          </Field>
          <Field label="Senha">
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
          </Field>
          {err && <div className="lc-error"><AlertTriangle size={15} /> {err}</div>}
          <button className="lc-btn lc-btn-login lc-btn-block" type="submit">Entrar</button>
        </form>
        <div className="lc-login-hint">
          <Lock size={13} /> Acesso restrito à equipe. Usuário inicial: <b>admin</b> / <b>admin123</b> — troque assim que possível em "Usuários".
        </div>
      </div>
    </div>
  );
}

function Sidebar({ currentUser, activeTab, setActiveTab, onLogout }) {
  const tabs = [
    { id: "dashboard", label: "Painel", icon: <LayoutDashboard size={18} /> },
    { id: "estoque", label: "Estoque", icon: <Package size={18} /> },
    { id: "vendas", label: "Vendas de rua", icon: <ShoppingBag size={18} /> },
    { id: "revendedores", label: "Revendedores", icon: <Users size={18} /> }
  ];
  if (currentUser.role === "admin") tabs.push({ id: "usuarios", label: "Usuários", icon: <UserCog size={18} /> });

  return (
    <aside className="lc-sidebar">
      <div className="lc-brand"><img src={LOGO_DATA_URI} alt="Le Cooki" className="lc-brand-logo" /> <span>Le Cooki</span></div>
      <nav>
        {tabs.map((t) => (
          <button
            key={t.id}
            className={"lc-nav-item" + (activeTab === t.id ? " lc-nav-active" : "")}
            onClick={() => setActiveTab(t.id)}
          >
            {t.icon} {t.label}
          </button>
        ))}
      </nav>
      <div className="lc-sidebar-foot">
        <div className="lc-user-chip">{currentUser.nome} <span className="lc-role-badge">{currentUser.role === "admin" ? "admin" : "equipe"}</span></div>
        <button className="lc-nav-item" onClick={onLogout}><LogOut size={18} /> Sair</button>
      </div>
    </aside>
  );
}

const CRITICAL_STOCK_LIMIT = 5;

function Dashboard({ db }) {
  const lowStock = db.products.filter((p) => p.estoqueAtual <= p.estoqueMinimo || p.estoqueAtual < CRITICAL_STOCK_LIMIT);
  const criticalStock = db.products.filter((p) => p.estoqueAtual < CRITICAL_STOCK_LIMIT);
  const month = todayISO().slice(0, 7);
  const monthSales = db.sales.filter((s) => s.data.slice(0, 7) === month);
  const monthTotal = monthSales.reduce((acc, s) => acc + Number(s.valor || 0), 0);
  const receivable = db.consignments
    .filter((c) => !c.pago)
    .reduce((acc, c) => acc + Number(c.quantidadeVendida || 0) * Number(c.precoUnit || 0), 0);
  const recentMov = [...db.stockMovements].sort((a, b) => (a.data < b.data ? 1 : -1)).slice(0, 6);

  return (
    <div>
      <h1 className="lc-page-title">Painel geral</h1>

      {criticalStock.length > 0 && (
        <div className="lc-alert-banner">
          <AlertTriangle size={18} />
          <div>
            <b>Estoque crítico:</b> {criticalStock.map((p) => p.nome).join(", ")} {criticalStock.length === 1 ? "está" : "estão"} com menos de {CRITICAL_STOCK_LIMIT} unidades.
          </div>
        </div>
      )}

      <div className="lc-stat-grid">
        <StatCard icon={<ShoppingBag size={20} />} label="Vendido este mês" value={fmtBRL(monthTotal)} />
        <StatCard icon={<Users size={20} />} label="A receber de revendedores" value={fmtBRL(receivable)} tone="accent" />
        <StatCard icon={<Package size={20} />} label="Produtos cadastrados" value={db.products.length} />
        <StatCard icon={<AlertTriangle size={20} />} label="Itens com estoque baixo" value={lowStock.length} tone={lowStock.length ? "warn" : "default"} />
      </div>

      <div className="lc-grid-2">
        <div className="lc-card">
          <h3>Estoque baixo</h3>
          {lowStock.length === 0 && <p className="lc-muted">Nenhum produto abaixo do mínimo. 🍪</p>}
          {lowStock.length > 0 && (
            <ul className="lc-simple-list">
              {lowStock.map((p) => (
                <li key={p.id}>
                  <span>{p.nome} {p.sabor && <em>({p.sabor})</em>}</span>
                  <span className="lc-badge lc-badge-warn">{p.estoqueAtual} un.</span>
                </li>
              ))}
            </ul>
          )}
        </div>
        <div className="lc-card">
          <h3>Últimas movimentações de estoque</h3>
          {recentMov.length === 0 && <p className="lc-muted">Sem movimentações registradas ainda.</p>}
          {recentMov.length > 0 && (
            <ul className="lc-simple-list">
              {recentMov.map((m) => (
                <li key={m.id}>
                  <span>
                    {m.tipo === "entrada" && <ArrowUpCircle size={14} className="lc-ok-icon" />}
                    {m.tipo === "saida" && <ArrowDownCircle size={14} className="lc-danger-icon" />}
                    {m.tipo === "avaria" && <PackageX size={14} className="lc-warn-icon" />}
                    {" "}{m.produtoNome} · {m.motivo}
                  </span>
                  <span className="lc-muted">{fmtDate(m.data)} · {m.quantidade} un.</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------------- ESTOQUE ---------------- */
function Estoque({ db, persist, showToast, currentUser }) {
  const [modal, setModal] = useState(null); // 'novo' | 'editar' | 'mov'
  const [editing, setEditing] = useState(null);
  const [movProduct, setMovProduct] = useState(null);
  const [movTipo, setMovTipo] = useState("entrada");

  const emptyForm = { nome: "", sabor: "", precoVenda: "", estoqueAtual: "", estoqueMinimo: "", observacao: "" };
  const [form, setForm] = useState(emptyForm);

  const openNew = () => { setForm(emptyForm); setEditing(null); setModal("novo"); };
  const openEdit = (p) => { setForm({ ...emptyForm, ...p }); setEditing(p.id); setModal("novo"); };

  const saveProduct = (e) => {
    e.preventDefault();
    const data = {
      id: editing || uid(),
      nome: form.nome.trim(),
      sabor: form.sabor.trim(),
      precoVenda: Number(form.precoVenda) || 0,
      estoqueAtual: Number(form.estoqueAtual) || 0,
      estoqueMinimo: Number(form.estoqueMinimo) || 0,
      observacao: (form.observacao || "").trim()
    };
    if (!data.nome) { showToast("Dê um nome ao produto.", "erro"); return; }
    let products;
    if (editing) products = db.products.map((p) => (p.id === editing ? data : p));
    else products = [...db.products, data];
    persist({ ...db, products });
    showToast(editing ? "Produto atualizado." : "Produto cadastrado.");
    setModal(null);
  };

  const removeProduct = (id) => {
    if (!confirm("Remover este produto do cadastro?")) return;
    persist({ ...db, products: db.products.filter((p) => p.id !== id) });
    showToast("Produto removido.");
  };

  const openMov = (p, tipo) => { setMovProduct(p); setMovTipo(tipo); setModal("mov"); };

  const submitMov = (e) => {
    e.preventDefault();
    const fd = new FormData(e.target);
    const quantidade = Number(fd.get("quantidade")) || 0;
    const motivo = fd.get("motivo") || (movTipo === "entrada" ? "Entrada manual" : movTipo === "avaria" ? "Avaria/perda" : "Saída manual");
    if (quantidade <= 0) { showToast("Informe uma quantidade válida.", "erro"); return; }
    const delta = movTipo === "entrada" ? quantidade : -quantidade;
    const novoEstoque = Math.max(0, movProduct.estoqueAtual + delta);
    const products = db.products.map((p) => (p.id === movProduct.id ? { ...p, estoqueAtual: novoEstoque } : p));
    const movement = {
      id: uid(), produtoId: movProduct.id, produtoNome: movProduct.nome,
      tipo: movTipo, quantidade, motivo, data: todayISO(), usuario: currentUser.nome
    };
    persist({ ...db, products, stockMovements: [...db.stockMovements, movement] });
    showToast(movTipo === "entrada" ? "Entrada registrada." : "Saída registrada.");
    setModal(null);
  };

  return (
    <div>
      <div className="lc-page-head">
        <h1 className="lc-page-title">Estoque</h1>
        <button className="lc-btn lc-btn-primary" onClick={openNew}><Plus size={16} /> Novo produto</button>
      </div>

      <div className="lc-card lc-no-pad">
        <table className="lc-table">
          <thead>
            <tr><th>Produto</th><th>Sabor</th><th>Preço</th><th>Estoque</th><th>Mínimo</th><th>Avarias</th><th>Observação</th><th></th></tr>
          </thead>
          <tbody>
            {db.products.length === 0 && (
              <tr><td colSpan={8} className="lc-empty">Nenhum produto cadastrado ainda. Clique em "Novo produto" para começar.</td></tr>
            )}
            {db.products.map((p) => {
              const avarias = db.stockMovements
                .filter((m) => m.produtoId === p.id && m.tipo === "avaria")
                .reduce((acc, m) => acc + Number(m.quantidade || 0), 0);
              const critico = p.estoqueAtual <= p.estoqueMinimo || p.estoqueAtual < CRITICAL_STOCK_LIMIT;
              return (
                <tr key={p.id}>
                  <td>{p.nome}</td>
                  <td>{p.sabor || "-"}</td>
                  <td>{fmtBRL(p.precoVenda)}</td>
                  <td><span className={"lc-badge" + (critico ? " lc-badge-warn" : " lc-badge-ok")}>{p.estoqueAtual}</span></td>
                  <td>{p.estoqueMinimo}</td>
                  <td>{avarias > 0 ? <span className="lc-badge lc-badge-warn">{avarias} un.</span> : "-"}</td>
                  <td className="lc-obs-cell">{p.observacao || "-"}</td>
                  <td className="lc-row-actions">
                    <button className="lc-icon-btn" title="Entrada" onClick={() => openMov(p, "entrada")}><ArrowUpCircle size={16} /></button>
                    <button className="lc-icon-btn" title="Saída" onClick={() => openMov(p, "saida")}><ArrowDownCircle size={16} /></button>
                    <button className="lc-icon-btn" title="Registrar avaria" onClick={() => openMov(p, "avaria")}><PackageX size={16} /></button>
                    <button className="lc-icon-btn" title="Editar" onClick={() => openEdit(p)}><Pencil size={15} /></button>
                    <button className="lc-icon-btn lc-icon-danger" title="Remover" onClick={() => removeProduct(p.id)}><Trash2 size={15} /></button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {modal === "novo" && (
        <Modal title={editing ? "Editar produto" : "Novo produto"} onClose={() => setModal(null)}>
          <form onSubmit={saveProduct}>
            <Field label="Nome do produto"><input value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} autoFocus /></Field>
            <Field label="Sabor / variação"><input value={form.sabor} onChange={(e) => setForm({ ...form, sabor: e.target.value })} /></Field>
            <div className="lc-field-row">
              <Field label="Preço de venda (R$)"><input type="number" step="0.01" value={form.precoVenda} onChange={(e) => setForm({ ...form, precoVenda: e.target.value })} /></Field>
              <Field label="Estoque atual"><input type="number" value={form.estoqueAtual} onChange={(e) => setForm({ ...form, estoqueAtual: e.target.value })} /></Field>
              <Field label="Estoque mínimo"><input type="number" value={form.estoqueMinimo} onChange={(e) => setForm({ ...form, estoqueMinimo: e.target.value })} /></Field>
            </div>
            <Field label="Observação (informação adicional)">
              <textarea rows={3} value={form.observacao} onChange={(e) => setForm({ ...form, observacao: e.target.value })} placeholder="Ex: validade, fornecedor, detalhe da receita..." />
            </Field>
            <button className="lc-btn lc-btn-primary lc-btn-block" type="submit">Salvar</button>
          </form>
        </Modal>
      )}

      {modal === "mov" && movProduct && (
        <Modal title={(movTipo === "entrada" ? "Entrada de estoque — " : movTipo === "avaria" ? "Registrar avaria — " : "Saída de estoque — ") + movProduct.nome} onClose={() => setModal(null)}>
          <form onSubmit={submitMov}>
            <Field label="Quantidade"><input name="quantidade" type="number" min="1" autoFocus /></Field>
            <Field label="Motivo">
              <input name="motivo" placeholder={movTipo === "entrada" ? "Ex: nova fornada" : movTipo === "avaria" ? "Ex: caiu, embalagem estufada, vencido" : "Ex: uso interno"} />
            </Field>
            <p className="lc-muted">Estoque atual: {movProduct.estoqueAtual} un.</p>
            <button className="lc-btn lc-btn-primary lc-btn-block" type="submit">Confirmar</button>
          </form>
        </Modal>
      )}
    </div>
  );
}

/* ---------------- VENDAS ---------------- */
function Vendas({ db, persist, showToast, currentUser }) {
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({ produtoId: "", quantidade: "", valor: "", pagamento: "Dinheiro", local: "", data: todayISO() });

  const openNew = () => {
    setForm({ produtoId: db.products[0]?.id || "", quantidade: "", valor: "", pagamento: "Dinheiro", local: "", data: todayISO() });
    setModal(true);
  };

  const produtoSelecionado = db.products.find((p) => p.id === form.produtoId);

  useEffect(() => {
    if (modal && produtoSelecionado && form.quantidade) {
      const sugerido = (Number(form.quantidade) * produtoSelecionado.precoVenda).toFixed(2);
      setForm((f) => ({ ...f, valor: sugerido }));
    }
    // eslint-disable-next-line
  }, [form.quantidade, form.produtoId]);

  const submit = (e) => {
    e.preventDefault();
    if (!form.produtoId) { showToast("Selecione um produto.", "erro"); return; }
    const quantidade = Number(form.quantidade) || 0;
    if (quantidade <= 0) { showToast("Informe a quantidade vendida.", "erro"); return; }
    const produto = db.products.find((p) => p.id === form.produtoId);
    if (produto && produto.estoqueAtual < quantidade) {
      showToast(`Atenção: estoque de "${produto.nome}" ficará negativo.`, "aviso");
    }
    const sale = {
      id: uid(), data: form.data, produtoId: form.produtoId, produtoNome: produto?.nome || "",
      quantidade, valor: Number(form.valor) || 0, pagamento: form.pagamento, local: form.local,
      vendedor: currentUser.nome
    };
    const products = db.products.map((p) => (p.id === form.produtoId ? { ...p, estoqueAtual: Math.max(0, p.estoqueAtual - quantidade) } : p));
    const movement = { id: uid(), produtoId: form.produtoId, produtoNome: produto?.nome || "", tipo: "saida", quantidade, motivo: "Venda de rua", data: form.data, usuario: currentUser.nome };
    persist({ ...db, products, sales: [...db.sales, sale], stockMovements: [...db.stockMovements, movement] });
    showToast("Venda registrada.");
    setModal(false);
  };

  const removeSale = (id) => {
    if (!confirm("Remover este registro de venda? (o estoque não será revertido automaticamente)")) return;
    persist({ ...db, sales: db.sales.filter((s) => s.id !== id) });
  };

  const sorted = [...db.sales].sort((a, b) => (a.data < b.data ? 1 : -1));

  return (
    <div>
      <div className="lc-page-head">
        <h1 className="lc-page-title">Vendas de rua</h1>
        <button className="lc-btn lc-btn-primary" onClick={openNew} disabled={db.products.length === 0}><Plus size={16} /> Nova venda</button>
      </div>
      {db.products.length === 0 && <p className="lc-muted">Cadastre ao menos um produto em "Estoque" antes de registrar vendas.</p>}

      <div className="lc-card lc-no-pad">
        <table className="lc-table">
          <thead><tr><th>Data</th><th>Produto</th><th>Qtd.</th><th>Valor</th><th>Pagamento</th><th>Local</th><th>Vendedor(a)</th><th></th></tr></thead>
          <tbody>
            {sorted.length === 0 && <tr><td colSpan={8} className="lc-empty">Nenhuma venda registrada ainda.</td></tr>}
            {sorted.map((s) => (
              <tr key={s.id}>
                <td>{fmtDate(s.data)}</td><td>{s.produtoNome}</td><td>{s.quantidade}</td>
                <td>{fmtBRL(s.valor)}</td><td>{s.pagamento}</td><td>{s.local || "-"}</td><td>{s.vendedor}</td>
                <td className="lc-row-actions"><button className="lc-icon-btn lc-icon-danger" onClick={() => removeSale(s.id)}><Trash2 size={15} /></button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {modal && (
        <Modal title="Nova venda de rua" onClose={() => setModal(false)}>
          <form onSubmit={submit}>
            <Field label="Produto">
              <select value={form.produtoId} onChange={(e) => setForm({ ...form, produtoId: e.target.value })}>
                {db.products.map((p) => <option key={p.id} value={p.id}>{p.nome}{p.sabor ? " - " + p.sabor : ""}</option>)}
              </select>
            </Field>
            <div className="lc-field-row">
              <Field label="Quantidade"><input type="number" min="1" value={form.quantidade} onChange={(e) => setForm({ ...form, quantidade: e.target.value })} autoFocus /></Field>
              <Field label="Valor total (R$)"><input type="number" step="0.01" value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} /></Field>
            </div>
            <div className="lc-field-row">
              <Field label="Forma de pagamento">
                <select value={form.pagamento} onChange={(e) => setForm({ ...form, pagamento: e.target.value })}>
                  <option>Dinheiro</option><option>Pix</option><option>Cartão de débito</option><option>Cartão de crédito</option>
                </select>
              </Field>
              <Field label="Data"><input type="date" value={form.data} onChange={(e) => setForm({ ...form, data: e.target.value })} /></Field>
            </div>
            <Field label="Local / evento (opcional)"><input value={form.local} onChange={(e) => setForm({ ...form, local: e.target.value })} placeholder="Ex: feira, encomenda avulsa..." /></Field>
            <button className="lc-btn lc-btn-primary lc-btn-block" type="submit">Registrar venda</button>
          </form>
        </Modal>
      )}
    </div>
  );
}

/* ---------------- REVENDEDORES ---------------- */
function Revendedores({ db, persist, showToast }) {
  const [modalReseller, setModalReseller] = useState(false);
  const [editingReseller, setEditingReseller] = useState(null);
  const [rForm, setRForm] = useState({ nome: "", contato: "", endereco: "", observacao: "" });
  const [expanded, setExpanded] = useState(null);
  const [modalConsig, setModalConsig] = useState(null); // reseller id
  const [cForm, setCForm] = useState({ produtoId: "", quantidade: "", precoUnit: "" });

  const openNewReseller = () => { setRForm({ nome: "", contato: "", endereco: "", observacao: "" }); setEditingReseller(null); setModalReseller(true); };
  const openEditReseller = (r) => { setRForm({ observacao: "", ...r }); setEditingReseller(r.id); setModalReseller(true); };

  const saveReseller = (e) => {
    e.preventDefault();
    if (!rForm.nome.trim()) { showToast("Dê um nome ao revendedor.", "erro"); return; }
    const data = { id: editingReseller || uid(), nome: rForm.nome.trim(), contato: rForm.contato.trim(), endereco: rForm.endereco.trim(), observacao: (rForm.observacao || "").trim() };
    const resellers = editingReseller ? db.resellers.map((r) => (r.id === editingReseller ? data : r)) : [...db.resellers, data];
    persist({ ...db, resellers });
    showToast(editingReseller ? "Revendedor atualizado." : "Revendedor cadastrado.");
    setModalReseller(false);
  };

  const removeReseller = (id) => {
    if (!confirm("Remover este revendedor e seu histórico de consignação?")) return;
    persist({ ...db, resellers: db.resellers.filter((r) => r.id !== id), consignments: db.consignments.filter((c) => c.revendedorId !== id) });
  };

  const openConsig = (rId) => {
    setCForm({ produtoId: db.products[0]?.id || "", quantidade: "", precoUnit: db.products[0]?.precoVenda || "" });
    setModalConsig(rId);
  };

  const submitConsig = (e) => {
    e.preventDefault();
    const produto = db.products.find((p) => p.id === cForm.produtoId);
    const quantidade = Number(cForm.quantidade) || 0;
    if (!produto || quantidade <= 0) { showToast("Selecione o produto e a quantidade.", "erro"); return; }
    const consig = {
      id: uid(), revendedorId: modalConsig, produtoId: produto.id, produtoNome: produto.nome,
      quantidadeEntregue: quantidade, quantidadeVendida: 0, quantidadeDevolvida: 0,
      precoUnit: Number(cForm.precoUnit) || produto.precoVenda, data: todayISO(), pago: false
    };
    const products = db.products.map((p) => (p.id === produto.id ? { ...p, estoqueAtual: Math.max(0, p.estoqueAtual - quantidade) } : p));
    const movement = { id: uid(), produtoId: produto.id, produtoNome: produto.nome, tipo: "saida", quantidade, motivo: "Entrega a revendedor", data: todayISO(), usuario: "" };
    persist({ ...db, products, consignments: [...db.consignments, consig], stockMovements: [...db.stockMovements, movement] });
    showToast("Entrega registrada.");
    setModalConsig(null);
  };

  const updateConsig = (id, patch) => {
    const consignments = db.consignments.map((c) => (c.id === id ? { ...c, ...patch } : c));
    persist({ ...db, consignments });
  };

  const removeConsig = (id) => {
    if (!confirm("Remover este registro de consignação?")) return;
    persist({ ...db, consignments: db.consignments.filter((c) => c.id !== id) });
  };

  return (
    <div>
      <div className="lc-page-head">
        <h1 className="lc-page-title">Revendedores</h1>
        <button className="lc-btn lc-btn-primary" onClick={openNewReseller}><Plus size={16} /> Novo revendedor</button>
      </div>

      {db.resellers.length === 0 && <p className="lc-muted">Nenhum revendedor cadastrado ainda.</p>}

      <div className="lc-reseller-list">
        {db.resellers.map((r) => {
          const items = db.consignments.filter((c) => c.revendedorId === r.id);
          const emPosse = items.reduce((a, c) => a + (c.quantidadeEntregue - c.quantidadeVendida - c.quantidadeDevolvida), 0);
          const aReceber = items.filter((c) => !c.pago).reduce((a, c) => a + c.quantidadeVendida * c.precoUnit, 0);
          const isOpen = expanded === r.id;
          return (
            <div className="lc-card lc-no-pad" key={r.id}>
              <button className="lc-reseller-head" onClick={() => setExpanded(isOpen ? null : r.id)}>
                {isOpen ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                <div className="lc-reseller-name">{r.nome}</div>
                <div className="lc-reseller-meta">{r.contato}</div>
                <div className="lc-reseller-stats">
                  <span className="lc-badge lc-badge-ok">{emPosse} un. em posse</span>
                  <span className="lc-badge lc-badge-warn">{fmtBRL(aReceber)} a receber</span>
                </div>
              </button>
              {isOpen && (
                <div className="lc-reseller-body">
                  <div className="lc-row-actions lc-mb">
                    <button className="lc-btn lc-btn-sm" onClick={() => openConsig(r.id)}><Plus size={14} /> Registrar entrega</button>
                    <button className="lc-btn lc-btn-sm lc-btn-ghost" onClick={() => openEditReseller(r)}><Pencil size={14} /> Editar dados</button>
                    <button className="lc-btn lc-btn-sm lc-btn-ghost lc-danger-text" onClick={() => removeReseller(r.id)}><Trash2 size={14} /> Remover revendedor</button>
                  </div>
                  {r.endereco && <p className="lc-muted">Endereço: {r.endereco}</p>}
                  {r.observacao && <p className="lc-muted">Obs.: {r.observacao}</p>}
                  <table className="lc-table">
                    <thead><tr><th>Data</th><th>Produto</th><th>Entregue</th><th>Vendida</th><th>Devolvida</th><th>Em posse</th><th>A receber</th><th>Status</th><th></th></tr></thead>
                    <tbody>
                      {items.length === 0 && <tr><td colSpan={9} className="lc-empty">Nenhuma entrega registrada.</td></tr>}
                      {items.map((c) => {
                        const posse = c.quantidadeEntregue - c.quantidadeVendida - c.quantidadeDevolvida;
                        const receber = c.quantidadeVendida * c.precoUnit;
                        return (
                          <tr key={c.id}>
                            <td>{fmtDate(c.data)}</td>
                            <td>{c.produtoNome}</td>
                            <td>{c.quantidadeEntregue}</td>
                            <td>
                              <input className="lc-mini-input" type="number" min="0" max={c.quantidadeEntregue - c.quantidadeDevolvida}
                                value={c.quantidadeVendida}
                                onChange={(e) => updateConsig(c.id, { quantidadeVendida: Math.max(0, Number(e.target.value) || 0) })} />
                            </td>
                            <td>
                              <input className="lc-mini-input" type="number" min="0" max={c.quantidadeEntregue - c.quantidadeVendida}
                                value={c.quantidadeDevolvida}
                                onChange={(e) => updateConsig(c.id, { quantidadeDevolvida: Math.max(0, Number(e.target.value) || 0) })} />
                            </td>
                            <td>{posse}</td>
                            <td>{fmtBRL(receber)}</td>
                            <td>
                              <button className={"lc-badge lc-badge-clickable " + (c.pago ? "lc-badge-ok" : "lc-badge-warn")} onClick={() => updateConsig(c.id, { pago: !c.pago })}>
                                {c.pago ? <><Check size={12} /> Pago</> : "Pendente"}
                              </button>
                            </td>
                            <td><button className="lc-icon-btn lc-icon-danger" onClick={() => removeConsig(c.id)}><Trash2 size={14} /></button></td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {modalReseller && (
        <Modal title={editingReseller ? "Editar revendedor" : "Novo revendedor"} onClose={() => setModalReseller(false)}>
          <form onSubmit={saveReseller}>
            <Field label="Nome"><input value={rForm.nome} onChange={(e) => setRForm({ ...rForm, nome: e.target.value })} autoFocus /></Field>
            <Field label="Contato (telefone/WhatsApp)"><input value={rForm.contato} onChange={(e) => setRForm({ ...rForm, contato: e.target.value })} /></Field>
            <Field label="Endereço / ponto de venda"><input value={rForm.endereco} onChange={(e) => setRForm({ ...rForm, endereco: e.target.value })} /></Field>
            <Field label="Observação (informação adicional)">
              <textarea rows={3} value={rForm.observacao} onChange={(e) => setRForm({ ...rForm, observacao: e.target.value })} placeholder="Ex: dia de entrega combinado, preferências..." />
            </Field>
            <button className="lc-btn lc-btn-primary lc-btn-block" type="submit">Salvar</button>
          </form>
        </Modal>
      )}

      {modalConsig && (
        <Modal title="Registrar entrega ao revendedor" onClose={() => setModalConsig(null)}>
          <form onSubmit={submitConsig}>
            <Field label="Produto">
              <select value={cForm.produtoId} onChange={(e) => {
                const p = db.products.find((x) => x.id === e.target.value);
                setCForm({ ...cForm, produtoId: e.target.value, precoUnit: p?.precoVenda || "" });
              }}>
                {db.products.map((p) => <option key={p.id} value={p.id}>{p.nome}{p.sabor ? " - " + p.sabor : ""}</option>)}
              </select>
            </Field>
            <div className="lc-field-row">
              <Field label="Quantidade entregue"><input type="number" min="1" value={cForm.quantidade} onChange={(e) => setCForm({ ...cForm, quantidade: e.target.value })} autoFocus /></Field>
              <Field label="Preço combinado (un.)"><input type="number" step="0.01" value={cForm.precoUnit} onChange={(e) => setCForm({ ...cForm, precoUnit: e.target.value })} /></Field>
            </div>
            {db.products.length === 0 && <p className="lc-muted">Cadastre um produto em "Estoque" primeiro.</p>}
            <button className="lc-btn lc-btn-primary lc-btn-block" type="submit" disabled={db.products.length === 0}>Registrar entrega</button>
          </form>
        </Modal>
      )}
    </div>
  );
}

/* ---------------- USUÁRIOS ---------------- */
function Usuarios({ db, persist, showToast, currentUser }) {
  const [modal, setModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ nome: "", username: "", password: "", role: "equipe" });

  const openNew = () => { setForm({ nome: "", username: "", password: "", role: "equipe" }); setEditing(null); setModal(true); };
  const openEdit = (u) => { setForm({ ...u, password: "" }); setEditing(u.id); setModal(true); };

  const submit = (e) => {
    e.preventDefault();
    if (!form.nome.trim() || !form.username.trim()) { showToast("Preencha nome e usuário.", "erro"); return; }
    const usernameTaken = db.users.some((u) => u.username.toLowerCase() === form.username.trim().toLowerCase() && u.id !== editing);
    if (usernameTaken) { showToast("Esse nome de usuário já existe.", "erro"); return; }
    let users;
    if (editing) {
      users = db.users.map((u) => u.id === editing
        ? { ...u, nome: form.nome.trim(), username: form.username.trim(), role: form.role, password: form.password ? form.password : u.password }
        : u);
    } else {
      if (!form.password) { showToast("Defina uma senha inicial.", "erro"); return; }
      users = [...db.users, { id: uid(), nome: form.nome.trim(), username: form.username.trim(), password: form.password, role: form.role }];
    }
    persist({ ...db, users });
    showToast(editing ? "Usuário atualizado." : "Usuário criado.");
    setModal(false);
  };

  const removeUser = (id) => {
    if (id === currentUser.id) { showToast("Você não pode remover seu próprio usuário.", "erro"); return; }
    if (db.users.filter((u) => u.role === "admin").length === 1 && db.users.find((u) => u.id === id)?.role === "admin") {
      showToast("É preciso manter ao menos um administrador.", "erro"); return;
    }
    if (!confirm("Remover este usuário?")) return;
    persist({ ...db, users: db.users.filter((u) => u.id !== id) });
  };

  return (
    <div>
      <div className="lc-page-head">
        <h1 className="lc-page-title">Usuários do sistema</h1>
        <button className="lc-btn lc-btn-primary" onClick={openNew}><Plus size={16} /> Novo usuário</button>
      </div>
      <p className="lc-muted">Este sistema foi feito para uso interno com login simples — indicado para a equipe de confiança, sem criptografia avançada de senha.</p>
      <div className="lc-card lc-no-pad">
        <table className="lc-table">
          <thead><tr><th>Nome</th><th>Usuário</th><th>Perfil</th><th></th></tr></thead>
          <tbody>
            {db.users.map((u) => (
              <tr key={u.id}>
                <td>{u.nome}</td><td>{u.username}</td>
                <td><span className={"lc-badge " + (u.role === "admin" ? "lc-badge-ok" : "")}>{u.role === "admin" ? "Administrador(a)" : "Equipe"}</span></td>
                <td className="lc-row-actions">
                  <button className="lc-icon-btn" onClick={() => openEdit(u)}><Pencil size={15} /></button>
                  <button className="lc-icon-btn lc-icon-danger" onClick={() => removeUser(u.id)}><Trash2 size={15} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {modal && (
        <Modal title={editing ? "Editar usuário" : "Novo usuário"} onClose={() => setModal(false)}>
          <form onSubmit={submit}>
            <Field label="Nome"><input value={form.nome} onChange={(e) => setForm({ ...form, nome: e.target.value })} autoFocus /></Field>
            <Field label="Usuário (login)"><input value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} /></Field>
            <Field label={editing ? "Nova senha (deixe em branco para manter)" : "Senha inicial"}>
              <input type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
            </Field>
            <Field label="Perfil">
              <select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
                <option value="equipe">Equipe</option>
                <option value="admin">Administrador(a)</option>
              </select>
            </Field>
            <button className="lc-btn lc-btn-primary lc-btn-block" type="submit">Salvar</button>
          </form>
        </Modal>
      )}
    </div>
  );
}

